    "whereas": {"en": "He enjoys reading, whereas his brother prefers sports.", "zh": "他喜欢阅读，而他的兄弟偏爱体育运动。"},
    "wherever": {"en": "You can use the app wherever you are.", "zh": "无论你在哪里，你都可以使用这个应用。"},
    "whichever": {"en": "You can take whichever book you like.", "zh": "你可以拿你喜欢的任何一本书。"},
    "whilst": {"en": "I heard the news whilst I was at work.", "zh": "在我工作的时候，我听到了这个消息。"},
